1	const PROCESSING_FEE = 5;
2	const PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
3	  sword: 110,
4	  amulet: 66,
5	};
6	
7	type Item = {
8	  type: string;
9	  material: string;
10	  enchantmentLevel: number;
11	  cursed: boolean;
12	};
13	
14	type Step = {
15	  op: string;
16	  items: Item[];
17	};
18	
19	type Scenario = {
20	  customer: { yearsWithMHPCO: number };
21	  steps: Step[];
22	};
23	
24	type QuoteResult = {
25	  premium: number;
26	};
27	
28	type ScenarioOutput = {
29	  results: QuoteResult[];
30	};
31	
32	const premiumForItems = (items: Item[]): number =>
33	  items.reduce((total, item) => total + PREMIUM_BY_ITEM_TYPE[item.type], 0);
34	
35	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
36	  results: scenario.steps.map((step) => ({
37	    premium: premiumForItems(step.items) + PROCESSING_FEE,
38	  })),
39	});
